// Prebuild gate: the committed downloadable PDF (public/reimagine-user-guide.pdf)
// must be built from the CURRENT chapter markdown. We hash src/data/user-guide/*.md
// and compare to the hash recorded when the PDF was last generated. Edit a chapter
// without regenerating -> mismatch -> build fails. This is what keeps the PDF from
// drifting the way the in-app guide (auto-rebuilt in prebuild) never can.
//
// Node-only on purpose: prebuild runs on Vercel, which has no Python. The PDF is
// regenerated by hand (npm run build:user-guide-pdf, which also updates the hash);
// this gate only verifies it wasn't forgotten.
//
// Fix on failure:  npm run build:user-guide-pdf
import fs from 'fs'
import { computeSourceHash, HASH_FILE, chapterFiles } from './lib/user-guide-hash.mjs'

const n = chapterFiles().length

if (!fs.existsSync(HASH_FILE)) {
  console.error('check-user-guide-pdf: FAIL — no source hash recorded for the PDF.')
  console.error('  Regenerate:  npm run build:user-guide-pdf')
  process.exit(1)
}

const recorded = fs.readFileSync(HASH_FILE, 'utf8').trim()
const current = computeSourceHash()

if (recorded !== current) {
  console.error('check-user-guide-pdf: FAIL — public/reimagine-user-guide.pdf is STALE.')
  console.error(`  A chapter in src/data/user-guide/ changed since the PDF was last built.`)
  console.error('  Regenerate:  npm run build:user-guide-pdf')
  process.exit(1)
}

console.log(`check-user-guide-pdf: OK (${n} chapters; PDF in sync with source)`)
